using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Profile;
namespace OrcaFacil.Web.Pages.Profile; [Authorize] public class IndexModel:PageModel{private readonly ICurrentUserService _current; private readonly ProfileService _service; public IndexModel(ICurrentUserService current,ProfileService service){_current=current;_service=service;} [BindProperty] public SaveIssuerProfileCommand Input{get;set;}=new(Guid.Empty,"",null,null,null,null,null,null,null); public async Task OnGetAsync(CancellationToken ct){var p=await _service.GetAsync(new(_current.UserId),ct); Input=new(_current.UserId,p?.BusinessName??"",p?.DocumentNumber,p?.Phone,p?.Email,p?.Address,p?.City,p?.PixKey,p?.LogoPath);} public async Task<IActionResult> OnPostAsync(CancellationToken ct){Input=Input with{UserId=_current.UserId}; var r=await _service.SaveAsync(Input,ct); if(!r.Succeeded){ModelState.AddModelError("",r.Error??"Erro ao salvar.");return Page();} TempData["Success"]="Perfil salvo."; return RedirectToPage();}}
